#include "../src/linux_privileged_jobs.hpp"
#include <cassert>
using namespace pcinsight;using namespace pcinsight::detail;
int main(){using Clock=PrivilegedJobObservation::Clock;const auto now=Clock::now();const auto deadline=now+std::chrono::hours(1);const std::string path="/org/freedesktop/systemd1/job/37";
    assert(valid_privileged_job_path(path)&&valid_privileged_job_path("/org/freedesktop/systemd1/job/4294967295"));for(const auto* bad:{"/org/freedesktop/systemd1/job/0","/org/freedesktop/systemd1/job/037","/org/freedesktop/systemd1/job/4294967296","/org/freedesktop/systemd1/job/"})assert(!valid_privileged_job_path(bad));
    PrivilegedJobObservation early("private.service",deadline);early.accept({37,path,"private.service","done"});assert(early.snapshot().state==PrivilegedJobState::pending);early.select(path);assert(early.snapshot().state==PrivilegedJobState::completed&&early.snapshot().succeeded.value==true);early.accept({37,path,"private.service","done"});assert(early.snapshot().state==PrivilegedJobState::completed);early.accept({37,path,"private.service","failed"});assert(early.snapshot().state==PrivilegedJobState::unknown&&!early.snapshot().succeeded.value);
    for(const auto* result:{"canceled","timeout","failed","dependency","skipped"}){PrivilegedJobObservation job("private.service",deadline);job.select(path);job.accept({37,path,"private.service",result});assert(job.snapshot().state==PrivilegedJobState::failed&&job.snapshot().succeeded.value==false);}
    PrivilegedJobObservation unrelated("private.service",deadline);unrelated.select(path);for(unsigned i=0;i<5000;++i)unrelated.accept({38,"/org/freedesktop/systemd1/job/38","elsewhere.service","done"});assert(unrelated.snapshot().state==PrivilegedJobState::pending);unrelated.accept({37,path,"alias.service","done"});assert(unrelated.snapshot().state==PrivilegedJobState::unknown);
    PrivilegedJobObservation unknown("private.service",deadline);unknown.select(path);unknown.accept({37,path,"private.service","future-result"});assert(unknown.snapshot().state==PrivilegedJobState::unknown&&unknown.snapshot().result.value=="future-result"&&!unknown.snapshot().succeeded.value);
    PrivilegedJobObservation expired("private.service",now-std::chrono::seconds(1));expired.accept({37,path,"private.service","done"});expired.select(path);assert(expired.snapshot().state==PrivilegedJobState::unknown);
    PrivilegedJobObservation timed("private.service",deadline);timed.select(path);assert(timed.snapshot(deadline).state==PrivilegedJobState::unknown);timed.accept({37,path,"private.service","done"});assert(timed.snapshot().state==PrivilegedJobState::unknown);
    for(const auto& bad:std::vector<PrivilegedJobEvent>{{38,path,"private.service","done"},{0,"/org/freedesktop/systemd1/job/0","private.service","done"},{37,"/org/freedesktop/systemd1/job/037","private.service","done"},{37,path,"private.service",std::string(65,'x')},{37,path,"private.service",""}}){PrivilegedJobObservation job("private.service",deadline);job.accept(bad);assert(job.snapshot().state==PrivilegedJobState::unknown);}
    PrivilegedJobObservation bounded("private.service",deadline);for(unsigned i=0;i<64;++i)bounded.accept({37,path,"private.service","done"});assert(bounded.snapshot().state==PrivilegedJobState::pending);bounded.accept({37,path,"private.service","done"});assert(bounded.snapshot().state==PrivilegedJobState::unknown);
    PrivilegedJobObservation closed("private.service",deadline);closed.select(path);closed.close_pending("closed");assert(closed.snapshot().state==PrivilegedJobState::unknown);
    PrivilegedJobObservation complete("private.service",deadline);complete.select(path);complete.accept({37,path,"private.service","done"});complete.close_pending("closed");assert(complete.snapshot().state==PrivilegedJobState::completed);
    assert(!create_privileged_job_watch(nullptr,":1.7","private.service",1000,true).value);
}
